begin;
create temp table checks(name text,passed boolean);
create function pg_temp.ok(v boolean,n text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',n;end if;insert into checks values(n,true);end$$;
create function pg_temp.deny(k text,p jsonb,n text) returns void language plpgsql as $$begin begin perform public.ig_mailbox_runtime(k,p);exception when others then insert into checks values(n,true);return;end;raise exception 'FAIL: %',n;end$$;
do $$declare uid uuid;sid uuid;other_uid uuid;claims jsonb;original_roles text[];r jsonb;msg uuid=gen_random_uuid();k text=repeat('a',64);h text=repeat('b',64);sealed jsonb='{"v":1,"data":"TEST ONLY encrypted envelope stand-in"}';begin
 select u.id,s.id into uid,sid from auth.users u join auth.sessions s on s.user_id=u.id where u.email='akm@indiagully.com' order by s.created_at desc limit 1;
 if sid is null then raise exception 'Owner session required';end if;
 select id into other_uid from auth.users where id<>uid limit 1;
 select p.roles into original_roles from public.ig_profiles p where id=uid;
 claims=jsonb_build_object('sub',uid,'session_id',sid,'aal','aal2','role','authenticated');perform set_config('request.jwt.claims',claims::text,true);
 update ig_private.integration_root set secret_hash=encode(extensions.digest(convert_to(k,'UTF8'),'sha256'),'hex');
 perform pg_temp.deny('wrong','{"action":"get"}','Runtime rejects missing server secret');
 perform public.ig_mailbox_runtime(k,jsonb_build_object('action','begin','state_hash',h));perform public.ig_mailbox_runtime(k,jsonb_build_object('action','consume','state_hash',h));perform pg_temp.deny(k,jsonb_build_object('action','consume','state_hash',h),'OAuth state is single-use');
 perform public.ig_mailbox_runtime(k,jsonb_build_object('action','begin','state_hash',h));update ig_private.mailbox_states set expires_at=now()-interval '1 minute' where user_id=uid;perform pg_temp.deny(k,jsonb_build_object('action','consume','state_hash',h),'Expired OAuth state rejected');
 perform pg_temp.deny(k,jsonb_build_object('action','connect','email','other@example.com','sealed',sealed),'Mailbox must match verified staff email');
 perform public.ig_mailbox_runtime(k,jsonb_build_object('action','connect','email','akm@indiagully.com','sealed',sealed));
 perform pg_temp.ok(public.ig_mailbox_runtime(k,'{"action":"get"}')->>'email'='akm@indiagully.com','Own connection available to authorised server');
 r=public.ig_mailbox_runtime(k,jsonb_build_object('action','draft','id',msg,'hash',h,'sealed',sealed));
 perform pg_temp.ok(r->>'status'='draft','Draft saves without sending');
 perform pg_temp.deny(k,jsonb_build_object('action','claim_send','id',msg,'hash',repeat('c',64),'version',1),'Changed content cannot be sent without review');
 perform public.ig_mailbox_runtime(k,jsonb_build_object('action','claim_send','id',msg,'hash',h,'version',1));
 perform pg_temp.deny(k,jsonb_build_object('action','claim_send','id',msg,'hash',h,'version',1),'Concurrent send cannot duplicate the message');
 perform public.ig_mailbox_runtime(k,jsonb_build_object('action','finish_send','id',msg,'status','uncertain'));
 perform pg_temp.deny(k,jsonb_build_object('action','claim_send','id',msg,'hash',h,'version',3),'Uncertain sends never automatically retry');
 if other_uid is not null then update ig_private.mailbox_messages set user_id=other_uid where id=msg;perform pg_temp.deny(k,jsonb_build_object('action','draft','id',msg,'hash',h,'sealed',sealed),'Another user message cannot be edited');perform pg_temp.ok(not exists(select 1 from jsonb_array_elements(public.ig_mailbox_runtime(k,'{"action":"dashboard"}')->'messages')m where m->>'id'=msg::text),'Another user message excluded from dashboard');end if;
 perform set_config('request.jwt.claims',(claims||'{"aal":"aal1"}')::text,true);perform pg_temp.deny(k,'{"action":"get"}','Mailbox requires staff MFA');
 perform set_config('request.jwt.claims',claims::text,true);update public.ig_profiles set roles=array['client'] where id=uid;perform pg_temp.deny(k,'{"action":"get"}','Client cannot access staff mailbox API');update public.ig_profiles set roles=original_roles where id=uid;
 perform public.ig_mailbox_runtime(k,'{"action":"disconnect"}');perform pg_temp.ok(public.ig_mailbox_runtime(k,'{"action":"get"}') is null,'Disconnect removes credentials');
 perform pg_temp.ok(not has_table_privilege('authenticated','ig_private.mailboxes','select') and not has_function_privilege('anon','public.ig_mailbox_runtime(text,jsonb)','execute'),'Direct credentials and anonymous API denied');
end $$;
select * from checks;
rollback;
